// ============================================
// CALCULATE NEXT ONBOARDING DATE
// ExampleCorp Munich: 1st or 15th of the month
// If weekend, shift to next Monday
// ============================================

const employee = $input.first().json;
const hireDate = new Date(employee.data.attributes.hire_date.value);
const today = new Date();

// Extract employee data
const firstName = employee.data.attributes.first_name.value;
const lastName = employee.data.attributes.last_name.value;
const email = employee.data.attributes.email.value;
const department = employee.data.attributes.department.value;
const position = employee.data.attributes.position.value;
const office = employee.data.attributes.office.value;

// Function: get next 1st or 15th after a given date
function getNextOnboardingDate(fromDate) {
  let candidates = [];

  // Check current month and next 2 months
  for (let m = 0; m <= 2; m++) {
    let d = new Date(fromDate);
    d.setMonth(d.getMonth() + m);

    // 1st of that month
    let first = new Date(d.getFullYear(), d.getMonth(), 1);
    candidates.push(first);

    // 15th of that month
    let fifteenth = new Date(d.getFullYear(), d.getMonth(), 15);
    candidates.push(fifteenth);
  }

  // Filter: must be >= hireDate and >= today
  let validDates = candidates.filter(d => d >= fromDate && d >= today);

  // Sort and get the earliest
  validDates.sort((a, b) => a - b);

  if (validDates.length === 0) return null;

  let onboardingDate = validDates[0];

  // If weekend, shift to next Monday
  const dayOfWeek = onboardingDate.getDay();
  if (dayOfWeek === 0) { // Sunday -> Monday (+1)
    onboardingDate.setDate(onboardingDate.getDate() + 1);
  } else if (dayOfWeek === 6) { // Saturday -> Monday (+2)
    onboardingDate.setDate(onboardingDate.getDate() + 2);
  }

  return onboardingDate;
}

const onboardingDate = getNextOnboardingDate(hireDate);

// Format date for display and Outlook
const dateOptions = { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' };
const formattedDate = onboardingDate.toLocaleDateString('de-DE', dateOptions);
const isoDate = onboardingDate.toISOString().split('T')[0];

// Outlook event times (09:00 - 17:00 CET)
const startDateTime = isoDate + 'T09:00:00';
const endDateTime = isoDate + 'T17:00:00';

return [{
  json: {
    employee: {
      firstName,
      lastName,
      fullName: `${firstName} ${lastName}`,
      email,
      department,
      position,
      office
    },
    onboarding: {
      date: isoDate,
      formattedDate,
      startDateTime,
      endDateTime,
      timeZone: 'W. Europe Standard Time',
      location: 'ExampleCorp Munich Office' // UPDATE: add exact address
    }
  }
}];

